const rawRows = Array.isArray($json.rows)
  ? $json.rows
  : [];

// Always Output Data may create one empty object for a zero-row result.
const rows = rawRows.filter(
  row =>
    row &&
    typeof row === 'object' &&
    Object.keys(row).length > 0
);

// Retrieve the validated information from the earlier safety node.
const validation =
  $('Validate SQL Safety').first().json;

const sql = validation.validated_sql ?? '';
const assumptions = validation.assumptions ?? [];
const citations = validation.citations ?? [];
const referencedTables = validation.referenced_tables ?? [];

const maximumDisplayedRows = 20;
const maximumDisplayedColumns = 8;

const displayedRows = rows.slice(0, maximumDisplayedRows);

function formatValue(value) {
  if (value === null || value === undefined) {
    return '';
  }

  if (typeof value === 'number') {
    return Number.isFinite(value)
      ? String(value)
      : '';
  }

  if (typeof value === 'boolean') {
    return value ? 'true' : 'false';
  }

  if (typeof value === 'object') {
    return JSON.stringify(value);
  }

  return String(value);
}

function escapeMarkdownCell(value) {
  return formatValue(value)
    .replace(/\|/g, '\\|')
    .replace(/\r?\n/g, ' ')
    .trim();
}

let resultSection;

if (displayedRows.length === 0) {
  resultSection = 'No rows were returned.';
} else {
  const allColumns = [
    ...new Set(
      displayedRows.flatMap(row => Object.keys(row))
    ),
  ];

  const displayedColumns =
    allColumns.slice(0, maximumDisplayedColumns);

  const header =
    '| ' + displayedColumns.join(' | ') + ' |';

  const divider =
    '| ' + displayedColumns.map(() => '---').join(' | ') + ' |';

  const body = displayedRows
    .map(row =>
      '| ' +
      displayedColumns
        .map(column => escapeMarkdownCell(row[column]))
        .join(' | ') +
      ' |'
    )
    .join('\n');

  const rowNotice =
    rows.length > maximumDisplayedRows
      ? `\n\nShowing ${maximumDisplayedRows} of ${rows.length} returned rows.`
      : `\n\nReturned ${rows.length} row${rows.length === 1 ? '' : 's'}.`;

  const columnNotice =
    allColumns.length > maximumDisplayedColumns
      ? ` Displaying ${maximumDisplayedColumns} of ${allColumns.length} columns.`
      : '';

  resultSection =
    header +
    '\n' +
    divider +
    '\n' +
    body +
    rowNotice +
    columnNotice;
}

const assumptionsSection =
  assumptions.length > 0
    ? assumptions.map(item => `- ${item}`).join('\n')
    : '- None';

const tableSection =
  referencedTables.length > 0
    ? referencedTables.map(table => `- ${table}`).join('\n')
    : '- None';

const citationSection =
  citations.length > 0
    ? citations.map(source => `- [${source}]`).join('\n')
    : '- None';

const output =
  'Query executed successfully using the read-only AdventureWorksDW connection.' +
  '\n\nSQL:\n```sql\n' +
  sql +
  '\n```' +
  '\n\nResults:\n' +
  resultSection +
  '\n\nTables:\n' +
  tableSection +
  '\n\nAssumptions:\n' +
  assumptionsSection +
  '\n\nSources:\n' +
  citationSection;

return {
  json: {
    output,
    execution_status: 'success',
    returned_row_count: rows.length,
    displayed_row_count: Math.min(
      rows.length,
      maximumDisplayedRows
    ),
  },
};

// Accept common n8n output structures.
const generated =
  $json.output ??
  $json.parsed ??
  $json;

const status = String(generated.status ?? '').trim().toLowerCase();
const sql = String(generated.sql ?? '').trim();

const validationErrors = [];
const validationChecks = {};

function recordCheck(name, passed, failureMessage) {
  validationChecks[name] = passed;

  if (!passed) {
    validationErrors.push(failureMessage);
  }
}

// Mask characters inside SQL string literals before scanning for keywords.
// Escaped single quotes such as '' are handled.
function maskStringLiterals(input) {
  let output = '';
  let insideString = false;

  for (let index = 0; index < input.length; index++) {
    const character = input[index];

    if (character === "'") {
      if (insideString && input[index + 1] === "'") {
        output += '  ';
        index++;
        continue;
      }

      insideString = !insideString;
      output += ' ';
      continue;
    }

    if (insideString) {
      output += character === '\n' ? '\n' : ' ';
    } else {
      output += character;
    }
  }

  return {
    masked: output,
    hasUnclosedString: insideString,
  };
}

const maskedResult = maskStringLiterals(sql);
const maskedSql = maskedResult.masked;

const normalizedSql = maskedSql
  .replace(/\s+/g, ' ')
  .trim()
  .toUpperCase();

// Internet Sales domain allowlist.
// Physical table references must be schema-qualified as dbo.TableName.
const allowedTables = new Set([
  'dbo.dimcurrency',
  'dbo.dimcustomer',
  'dbo.dimdate',
  'dbo.dimgeography',
  'dbo.dimproduct',
  'dbo.dimproductcategory',
  'dbo.dimproductsubcategory',
  'dbo.dimpromotion',
  'dbo.dimsalesterritory',
  'dbo.factinternetsales',
]);

/*
 * Non-ready generation results are never eligible for execution.
 *
 * Examples:
 * - unsupported destructive request
 * - ambiguous request requiring clarification
 * - missing catalog information
 */
if (status !== 'ready') {
  recordCheck(
    'non_ready_has_empty_sql',
    sql.length === 0,
    'A non-ready response unexpectedly contained SQL.'
  );

  return {
    json: {
      status,
      answer: generated.answer ?? '',
      sql,
      tables_used: generated.tables_used ?? [],
      assumptions: generated.assumptions ?? [],
      citations: generated.citations ?? [],
      validation_checks: validationChecks,
      validation_errors: validationErrors,
      referenced_tables: [],
      safety_passed: false,
      execution_eligible: false,
      validated_sql: '',
    },
  };
}

/*
 * Checks below apply only when the model returned status = ready.
 */

// SQL must be present.
recordCheck(
  'sql_is_present',
  sql.length > 0,
  'The generated SQL is empty.'
);

// Prevent unexpectedly large generated statements.
recordCheck(
  'sql_length_is_reasonable',
  sql.length <= 10000,
  'The generated SQL exceeds the 10,000-character safety limit.'
);

// Reject malformed or unfinished string literals.
recordCheck(
  'string_literals_are_balanced',
  !maskedResult.hasUnclosedString,
  'The query contains an unclosed SQL string literal.'
);

// Permit one statement with an optional trailing semicolon.
const statements = maskedSql
  .split(';')
  .map(statement => statement.trim())
  .filter(Boolean);

recordCheck(
  'single_statement',
  statements.length === 1,
  'Only one SQL statement is allowed.'
);

// Queries must start with SELECT or WITH.
recordCheck(
  'read_only_start',
  /^(SELECT|WITH)\b/i.test(sql),
  'The query must begin with SELECT or WITH.'
);

// Reject comments because they can conceal appended SQL.
recordCheck(
  'no_comments',
  !/(--|\/\*|\*\/)/.test(maskedSql),
  'SQL comments are not allowed.'
);

// Block data modification, DDL, administration, dynamic SQL,
// external data access, and SELECT INTO.
const blockedKeywordPattern =
  /\b(INSERT|UPDATE|DELETE|MERGE|DROP|ALTER|CREATE|TRUNCATE|EXEC|EXECUTE|DECLARE|SET|USE|GRANT|REVOKE|DENY|BACKUP|RESTORE|DBCC|SHUTDOWN|KILL|WAITFOR|BULK|INTO|OPENROWSET|OPENDATASOURCE|OPENQUERY|OPENXML)\b/i;

recordCheck(
  'no_blocked_keywords',
  !blockedKeywordPattern.test(normalizedSql),
  'The query contains a blocked SQL keyword.'
);

// Block calls to extended and system stored procedures.
recordCheck(
  'no_extended_or_system_procedures',
  !/\b(XP_|SP_)/i.test(normalizedSql),
  'Extended or system stored procedures are not allowed.'
);

// The assistant does not need SQL Server system metadata.
recordCheck(
  'no_system_catalog_access',
  !/\b(INFORMATION_SCHEMA|SYS\s*\.)/i.test(normalizedSql),
  'System catalog access is not allowed.'
);

// Reject SELECT * and alias.*.
const selectStarPattern =
  /\bSELECT\s+(?:TOP\s*(?:\(\s*\d+\s*\)|\d+)\s+)?(?:DISTINCT\s+)?(?:[A-Za-z_][\w]*\s*\.\s*)?\*/i;

recordCheck(
  'no_select_star',
  !selectStarPattern.test(maskedSql),
  'SELECT * and alias.* are not allowed.'
);

/*
 * Detect CTE names.
 *
 * A CTE may be referenced using only its one-part name.
 * Physical tables must still use schema.table.
 */
const cteNames = new Set();

const ctePattern =
  /(?:\bWITH|,)\s*(\[[^\]]+\]|[A-Za-z_][\w$#@]*)\s+AS\s*\(/gi;

let cteMatch;

while ((cteMatch = ctePattern.exec(maskedSql)) !== null) {
  const cteName = cteMatch[1]
    .replace(/[\[\]]/g, '')
    .toLowerCase();

  cteNames.add(cteName);
}

/*
 * Extract identifiers following FROM and JOIN.
 *
 * Supported physical format:
 *   dbo.TableName
 *   [dbo].[TableName]
 *
 * One-part identifiers are allowed only for recognized CTEs.
 * Three-part and four-part identifiers are rejected.
 */
const tablePattern =
  /\b(?:FROM|JOIN)\s+((?:\[[^\]]+\]|[A-Za-z_][\w$#@]*)(?:\s*\.\s*(?:\[[^\]]+\]|[A-Za-z_][\w$#@]*)){0,3})/gi;

const referencedTables = [];
const invalidTableReferences = [];

let tableMatch;

while ((tableMatch = tablePattern.exec(maskedSql)) !== null) {
  const rawIdentifier = tableMatch[1];

  const parts = rawIdentifier
    .split('.')
    .map(part =>
      part
        .replace(/[\[\]\s]/g, '')
        .toLowerCase()
    )
    .filter(Boolean);

  // Allow one-part references only when they refer to a known CTE.
  if (parts.length === 1 && cteNames.has(parts[0])) {
    continue;
  }

  // Physical tables must use exactly schema.table.
  if (parts.length !== 2) {
    invalidTableReferences.push(rawIdentifier);
    continue;
  }

  const normalizedTable = `${parts[0]}.${parts[1]}`;
  referencedTables.push(normalizedTable);

  if (!allowedTables.has(normalizedTable)) {
    invalidTableReferences.push(rawIdentifier);
  }
}

const uniqueReferencedTables = [...new Set(referencedTables)];

recordCheck(
  'references_physical_tables',
  uniqueReferencedTables.length > 0,
  'The validator could not identify an approved physical table.'
);

recordCheck(
  'tables_are_allowlisted',
  invalidTableReferences.length === 0,
  invalidTableReferences.length > 0
    ? `Unapproved table references: ${[
        ...new Set(invalidTableReferences),
      ].join(', ')}`
    : 'All physical tables are allowlisted.'
);

/*
 * Validate TOP.
 *
 * If TOP is present, it must be a fixed integer from 1 through 100.
 */
const topMatch = maskedSql.match(
  /\bTOP\s*(?:\(\s*(\d+)\s*\)|(\d+))/i
);

const topValue = topMatch
  ? Number(topMatch[1] ?? topMatch[2])
  : null;

recordCheck(
  'top_is_within_limit',
  topValue === null ||
    (Number.isInteger(topValue) && topValue >= 1 && topValue <= 100),
  'TOP must be a fixed integer between 1 and 100.'
);

/*
 * Detail-level queries require TOP.
 *
 * Aggregate and grouped queries are allowed without TOP because they return
 * summarized results.
 */
const containsAggregate =
  /\b(SUM|COUNT|AVG|MIN|MAX)\s*\(/i.test(maskedSql);

const containsGroupBy =
  /\bGROUP\s+BY\b/i.test(maskedSql);

const appearsToBeDetailQuery =
  !containsAggregate && !containsGroupBy;

recordCheck(
  'detail_query_has_row_limit',
  !appearsToBeDetailQuery || topValue !== null,
  'Nonaggregate detail queries must include TOP with a maximum of 100.'
);

// The query passes only when every deterministic check succeeds.
const safetyPassed = validationErrors.length === 0;

return {
  json: {
    status,
    answer: generated.answer ?? '',
    sql,
    tables_used: generated.tables_used ?? [],
    assumptions: generated.assumptions ?? [],
    citations: generated.citations ?? [],
    validation_checks: validationChecks,
    validation_errors: validationErrors,
    referenced_tables: uniqueReferencedTables,
    safety_passed: safetyPassed,
    execution_eligible: status === 'ready' && safetyPassed,
    validated_sql: safetyPassed ? sql : '',
  },
};
